<?php include 'verifica_login.php'; if (!validar_csrf($_GET['csrf_token'] ?? null)) { http_response_code(403); exit('Solicitação inválida.'); } include 'conexao.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id||$id<1) die('ID inválido.'); mysqli_begin_transaction($conexao); try{ if(!mysqli_query($conexao,"DELETE FROM artigo_autor WHERE id_autor=$id")) throw new Exception(mysqli_error($conexao)); if(!mysqli_query($conexao,"DELETE FROM autores WHERE id_autor=$id")) throw new Exception(mysqli_error($conexao)); mysqli_commit($conexao); header('Location: lista_autores.php'); exit;}catch(Exception $e){mysqli_rollback($conexao); die('Não foi possível excluir o autor: '.htmlspecialchars($e->getMessage()));}
